"""Restored line/prompt transport with prompt and echo modes through fake serial."""

import pytest

from coherent_verdi import DeviceError, VerdiController
from coherent_verdi.__main__ import main


def frame(payload, instruction, *, prompt=True, echo=False):
    """Independent wire examples, not generated by the production simulator."""
    line = (instruction + b" " if echo else b"") + payload
    return line + b"\r\n" + (b"Verdi V-2>" if prompt else b"")


def test_native_exchange_uses_read_until_without_reconfiguring_each_byte(peer, monkeypatch):
    wire = b"level1 set!\r\nlevel0 set!\r\n0.114\r\nVerdi V-2>"
    peer.responses.append(wire)
    settings, reads = [], []
    assign = type(peer).__setattr__
    read_until = peer.read_until

    def record_setting(handle, name, value):
        if handle is peer and name in ("timeout", "write_timeout"):
            settings.append((name, value))
        assign(handle, name, value)

    def receive(expected=b"\n", size=None):
        reads.append((expected, peer.timeout))
        return read_until(expected, size)

    def no_pause(seconds):
        raise AssertionError("native exchanges must not add an inter-query pause")

    monkeypatch.setattr(type(peer), "__setattr__", record_setting)
    monkeypatch.setattr(peer, "read_until", receive)
    monkeypatch.setattr("time.sleep", no_pause)
    with VerdiController("FAKE-ONLY", model="V2", timeout_s=0.75) as laser:
        assert laser.get_power_w() == 0.114
        assert laser.last_transaction["response"] == wire and not peer.pending
    assert settings == [("timeout", 0.75), ("write_timeout", 0.75)]
    assert reads == [(b"\r\n", 0.75)] * 3 + [(b">", 0.75)]
    assert peer.writes == [b"?P\r\n"]


@pytest.mark.parametrize("enabled", [False, True])
def test_echo_setting_and_next_read_remain_supported(peer, enabled):
    instruction = b"E=1" if enabled else b"E=0"
    peer.responses.extend(
        [
            frame(b"", instruction, echo=enabled),
            frame(b"6.05", b"?SV", echo=enabled),
        ]
    )
    with VerdiController("FAKE-ONLY", model="V2", allow_writes=True) as laser:
        laser.set_echo(enabled=enabled)
        assert laser.get_value("?SV") == "6.05" and not peer.pending
    assert peer.writes == [instruction + b"\r\n", b"?SV\r\n"]


@pytest.mark.parametrize("prompt", [False, True])
@pytest.mark.parametrize("echo", [False, True])
def test_query_acknowledgment_and_readback_consume_each_complete_frame(peer, prompt, echo):
    exchanges = [(b"?P", b"0.114"), (b"P=0.1000", b""), (b"?SP", b"0.1000")]
    wires = [frame(p, q, prompt=prompt, echo=echo) for q, p in exchanges]
    peer.responses.extend(wires)
    with VerdiController(
        "FAKE-ONLY",
        model="V2",
        prompt_enabled=prompt,
        allow_writes=True,
    ) as laser:
        assert not peer.writes
        assert laser.get_power_w() == 0.114
        assert laser.last_transaction["response"] == wires[0] and not peer.pending
        laser.set_power_w(0.1)
        assert laser.last_transaction["outcome"] == "acknowledged"
        assert laser.last_transaction["response"] == wires[1] and not peer.pending
        assert laser.get_value("?SP") == 0.1
        assert laser.last_transaction["response"] == wires[2] and not peer.pending
    assert peer.writes == [q + b"\r\n" for q, _ in exchanges]


@pytest.mark.parametrize("echo", [False, True])
@pytest.mark.parametrize(
    "instruction,error",
    [
        (b"P=0.1", b"RANGE ERROR: P=0.1"),
        (b"S=1", b"Command Error: S=1"),
        (b"?P", b"Query Error: ?P"),
    ],
)
def test_documented_device_rejections_keep_next_exchange_aligned(peer, echo, instruction, error):
    wire = frame(error, instruction, echo=echo)
    peer.responses.extend([wire, frame(b"6.05", b"?SV", echo=echo)])
    with VerdiController("FAKE-ONLY", model="V2", allow_writes=True) as laser:
        with pytest.raises(DeviceError) as caught:
            if instruction.startswith(b"?"):
                laser.get_value(instruction.decode())
            else:
                laser.set_value(instruction.decode())
        assert caught.value.transaction["response"] == wire
        assert laser.last_transaction["outcome"] == "rejected"
        assert not laser.failed and not peer.pending
        assert laser.get_value("?SV") == "6.05" and not peer.pending
    assert peer.writes == [instruction + b"\r\n", b"?SV\r\n"]


@pytest.mark.parametrize("initial_prompt", [False, True])
@pytest.mark.parametrize("echo", [False, True])
def test_successful_prompt_changes_apply_the_new_framing_to_the_acknowledgment(
    peer, initial_prompt, echo
):
    new_prompt = not initial_prompt
    instruction = b"PROMPT=0" if new_prompt else b"PROMPT=1"
    peer.responses.extend(
        [
            frame(b"", instruction, prompt=new_prompt, echo=echo),
            frame(b"6.05", b"?SV", prompt=new_prompt, echo=echo),
        ]
    )
    with VerdiController(
        "FAKE-ONLY",
        model="V2",
        prompt_enabled=initial_prompt,
        allow_writes=True,
    ) as laser:
        laser.set_prompt(enabled=new_prompt)
        assert laser._prompt_enabled is new_prompt and not peer.pending
        assert laser.get_value("?SV") == "6.05" and not peer.pending
    assert peer.writes == [instruction + b"\r\n", b"?SV\r\n"]


@pytest.mark.parametrize("initial_prompt", [False, True])
def test_rejected_prompt_change_does_not_change_the_receive_mode(peer, initial_prompt):
    instruction = b"PROMPT=1" if initial_prompt else b"PROMPT=0"
    peer.responses.extend(
        [
            frame(b"Command Error: " + instruction, instruction, prompt=initial_prompt),
            frame(b"6.05", b"?SV", prompt=initial_prompt),
        ]
    )
    with VerdiController(
        "FAKE-ONLY",
        model="V2",
        prompt_enabled=initial_prompt,
        allow_writes=True,
    ) as laser:
        with pytest.raises(DeviceError):
            laser.set_prompt(enabled=not initial_prompt)
        assert laser._prompt_enabled is initial_prompt and not peer.pending
        assert laser.get_value("?SV") == "6.05" and not peer.pending


def test_binary_payload_capture_and_consecutive_notices_preserve_all_bytes(peer):
    payload = b"\x00\xff\x96>"
    wire = b"level1 set!\r\nlevel0 set!\r\n" + frame(payload, b"?SV", echo=True)
    peer.responses.append(wire)
    with VerdiController("FAKE-ONLY", model="V2") as laser:
        result = laser.get_capture("?SV")
        assert result["payload"] == payload
        assert result["response"] == wire and not peer.pending


@pytest.mark.parametrize(
    "chunks",
    [
        [b"level1 set!\r", b"\nlevel0 set!\r\n", b"0.114\r", b"\nVerdi", b" V-2>"],
    ],
)
def test_fragmented_delivery_does_not_complete_at_an_empty_receive_queue(peer, monkeypatch, chunks):
    chunks = list(chunks)
    peer.responses.append(chunks.pop(0))
    read = peer.read

    def fragmented(size):
        if not peer.pending and chunks:
            peer.pending.extend(chunks.pop(0))
        return read(size)

    monkeypatch.setattr(peer, "read", fragmented)
    with VerdiController("FAKE-ONLY", model="V2") as laser:
        assert laser.get_power_w() == 0.114
        assert not chunks and not peer.pending
        assert not laser.failed
    assert peer.writes == [b"?P\r\n"]


def test_cli_raw_commission_consumes_the_reply_and_prompt(peer, capsys):
    import json

    wire = frame(b"6.05", b"?SV")
    peer.responses.append(wire)
    assert main(["--port", "FAKE-ONLY", "--model", "V2", "commission"]) == 0
    record = json.loads(capsys.readouterr().out)
    assert bytes.fromhex(record["response_hex"]) == wire
    assert record["payload"] == "6.05"
    assert peer.writes == [b"?SV\r\n"] and not peer.pending


def test_gui_session_consumes_the_native_reply_and_prompt(peer):
    from coherent_verdi.gui import GuiSession

    session = GuiSession(port="FAKE-ONLY", model="V2")
    session.submit("connect")
    session.step()
    assert session.snapshot()["state"] == "CONNECTED" and not peer.writes
    try:
        laser = session.monitor.controller
        peer.responses.append(frame(b"6.05", b"?SV"))
        assert laser.get_value("?SV") == "6.05" and not peer.pending
    finally:
        session.submit("close")
        session.step()
    assert peer.opens == peer.closes == 1
